package pe.edu.grupo4.carga.service;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.edu.grupo4.base.entity.*; import pe.edu.grupo4.base.repository.*; import pe.edu.grupo4.carga.dto.*; import pe.edu.grupo4.carga.entity.CargaAcademica; import pe.edu.grupo4.carga.mapper.CargaAcademicaMapper; import pe.edu.grupo4.carga.repository.CargaAcademicaRepository; import pe.edu.grupo4.shared.exception.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class CargaAcademicaServiceImpl implements CargaAcademicaService {
 private final CargaAcademicaRepository cargas; private final DocenteRepository docentes; private final CursoRepository cursos; private final SedeRepository sedes; private final DisponibilidadDocenteRepository disponibilidades;
 @Override public CargaAcademicaResponse crear(CargaAcademicaRequest r){CargaAcademica c=from(r);validar(c,null);return toDto(cargas.save(c));}
 @Override public CargaAcademicaResponse actualizar(Long id,CargaAcademicaRequest r){CargaAcademica old=buscar(id);if(old.getEstado()!=CargaAcademica.EstadoCarga.ACTIVA)throw new ConflictoNegocioException("No se puede editar una carga anulada");CargaAcademica c=from(r);c.setId(id);validar(c,id);return toDto(cargas.save(c));}
 @Override @Transactional(readOnly=true) public CargaAcademicaResponse obtener(Long id){return toDto(buscar(id));}
 @Override @Transactional(readOnly=true) public List<CargaAcademicaResponse> listar(String ciclo,Long sedeId,Long docenteId){return cargas.findByEstado(CargaAcademica.EstadoCarga.ACTIVA).stream().filter(c->ciclo==null||c.getCicloAcademico().equals(ciclo)).filter(c->sedeId==null||c.getSede().getId().equals(sedeId)).filter(c->docenteId==null||c.getDocente().getId().equals(docenteId)).map(this::toDto).toList();}
 @Override public void anular(Long id){CargaAcademica c=buscar(id);c.setEstado(CargaAcademica.EstadoCarga.ANULADA);cargas.save(c);}
 private CargaAcademica buscar(Long id){return cargas.findById(id).orElseThrow(()->new RecursoNoEncontradoException("No existe la carga académica "+id));}
 private CargaAcademica from(CargaAcademicaRequest r){if(!r.horaFin().isAfter(r.horaInicio()))throw new IllegalArgumentException("La hora fin debe ser posterior a la hora inicio");Docente docente=docentes.findById(r.docenteId()).orElseThrow(()->new RecursoNoEncontradoException("No existe el docente "+r.docenteId()));Curso curso=cursos.findById(r.cursoId()).orElseThrow(()->new RecursoNoEncontradoException("No existe el curso "+r.cursoId()));Sede sede=sedes.findById(r.sedeId()).orElseThrow(()->new RecursoNoEncontradoException("No existe la sede "+r.sedeId()));return CargaAcademicaMapper.toEntity(r,docente,curso,sede);}
 private void validar(CargaAcademica c,Long excludedId){Docente d=c.getDocente();if(!d.getEspecialidad().equalsIgnoreCase(c.getCurso().getEspecialidadRequerida()))throw new ConflictoNegocioException("Especialidad incompatible: el curso requiere "+c.getCurso().getEspecialidadRequerida()+" y el docente tiene "+d.getEspecialidad());List<CargaAcademica> sameDay=cargas.findByDocenteIdAndEstado(d.getId(),CargaAcademica.EstadoCarga.ACTIVA).stream().filter(x->excludedId==null||!x.getId().equals(excludedId)).filter(x->x.getCicloAcademico().equals(c.getCicloAcademico())&&x.getDiaSemana()==c.getDiaSemana()).toList();for(CargaAcademica x:sameDay){if(c.getHoraInicio().isBefore(x.getHoraFin())&&c.getHoraFin().isAfter(x.getHoraInicio()))throw new ConflictoNegocioException("Cruce horario con "+x.getCurso().getNombre()+" ("+x.getHoraInicio()+"–"+x.getHoraFin()+") en "+x.getSede().getNombre());if(!c.getSede().getId().equals(x.getSede().getId())){long gap;if(!c.getHoraFin().isAfter(x.getHoraInicio()))gap=Duration.between(c.getHoraFin(),x.getHoraInicio()).toMinutes();else gap=Duration.between(x.getHoraFin(),c.getHoraInicio()).toMinutes();if(gap<60)throw new ConflictoNegocioException("Tiempo de traslado insuficiente entre "+c.getSede().getNombre()+" y "+x.getSede().getNombre()+": se requieren 60 minutos y hay "+Math.max(gap,0)+" minutos");}}
 boolean available=disponibilidades.findByDocenteIdAndDiaSemana(d.getId(),c.getDiaSemana()).stream().anyMatch(v->v.getSede().getId().equals(c.getSede().getId())&&!c.getHoraInicio().isBefore(v.getHoraInicio())&&!c.getHoraFin().isAfter(v.getHoraFin()));if(!available)throw new ConflictoNegocioException("Horario fuera de disponibilidad del docente para "+c.getDiaSemana()+" en "+c.getSede().getNombre());double hours=sameCycleHours(d.getId(),c.getCicloAcademico(),excludedId)+duration(c);int max=d.getMaxHorasSemanales()>0?d.getMaxHorasSemanales():20;if(hours>max)throw new ConflictoNegocioException("Se excede el máximo de "+max+" horas semanales del docente (resultado: "+hours+")");}
 private double sameCycleHours(Long doc,String ciclo,Long excluded){return cargas.findByDocenteIdAndEstado(doc,CargaAcademica.EstadoCarga.ACTIVA).stream().filter(x->excluded==null||!x.getId().equals(excluded)).filter(x->x.getCicloAcademico().equals(ciclo)).mapToDouble(this::duration).sum();}
 private double duration(CargaAcademica c){return c.getCurso().getHorasSemanales();}
 private CargaAcademicaResponse toDto(CargaAcademica c){return CargaAcademicaMapper.toResponse(c,sameCycleHours(c.getDocente().getId(),c.getCicloAcademico(),c.getId())+(c.getEstado()==CargaAcademica.EstadoCarga.ACTIVA?duration(c):0));}
}
